input.content:
* { box-sizing: border-box; }
:root { color-scheme: light; --ink:#2b4842; --muted:#758b83; --cream:#fffdf6; --green:#315d4e; --pale:#eaf1e9; }
html, body { width:100%; min-width:320px; min-height:100%; margin:0; }
body { background:#e9f1e9; color:var(--ink); font-family:'DM Sans',sans-serif; display:flex; justify-content:center; }
button { font:inherit; }
.game-shell { width:min(100%,1600px); min-height:100svh; overflow:hidden; background:var(--cream); box-shadow:0 12px 60px #315d4e12; display:flex; flex-direction:column; }
.island-scene { height: min(67vh,680px); min-height:460px; position:relative; overflow:hidden; background:#b9ded5; }
#scene { position:absolute; inset:0; width:100%; height:100%; }
.scene-shade { position:absolute; inset:0; pointer-events:none; background:linear-gradient(180deg,rgba(239,249,241,.15) 0%,transparent 23%,transparent 74%,rgba(28,78,71,.10) 100%); }
.sun-glow { position:absolute; width:320px; height:320px; top:5%; left:60%; pointer-events:none; background:radial-gradient(circle,#fff6c77a 0,transparent 70%); }
.topbar { position:absolute; z-index:2; left:clamp(22px,5.4vw,82px); right:clamp(22px,5.4vw,82px); top:26px; display:flex; align-items:center; justify-content:space-between; }
.brand { display:flex; gap:11px; align-items:center; text-decoration:none; color:#31574e; font-family:Fraunces,serif; font-size:22px; font-weight:700; letter-spacing:-.7px; }
.brand-mark { display:grid; place-items:center; border-radius:50%; width:39px; height:39px; background:#fffdf3d9; color:#dd9d5a; font-family:'DM Sans',sans-serif; font-size:22px; box-shadow:0 4px 14px #36574b15; }
.brand-sub { display:block; font-family:'DM Sans',sans-serif; font-size:9px; line-height:1.2; letter-spacing:1.55px; text-transform:uppercase; font-weight:600; color:#58776c; }
.top-actions { display:flex; gap:10px; align-items:center; }
.weather { display:flex; align-items:center; gap:8px; padding:10px 15px; border:1px solid #fff9; border-radius:25px; background:#fffcf0d9; color:#486258; font-size:12px; font-weight:700; box-shadow:0 4px 16px #28493c10; }
.weather-icon { color:#d79745; font-size:18px; }.weather small { font-size:11px; font-weight:500; color:#81938a; }
.icon-button { border:1px solid #fff9; height:38px; width:38px; border-radius:50%; background:#fffcf0d9; color:#527267; cursor:pointer; font-size:18px; display:grid; place-items:center; transition:transform .18s,background .18s; box-shadow:0 4px 16px #28493c10; }
.icon-button:hover { transform:translateY(-2px); background:#fff; }
#help-button { font-family:Fraunces,serif; font-weight:700; font-size:16px; }
.scene-caption { position:absolute; left:clamp(24px,5.5vw,84px); bottom:35px; display:flex; align-items:center; gap:10px; color:#fffdf4; font-size:10px; font-weight:700; letter-spacing:2px; text-shadow:0 1px 5px #204a45aa; }
.caption-dot { width:7px; height:7px; border-radius:50%; background:#ffdda0; box-shadow:0 0 10px #ffe4a8; }.caption-line { width:26px; height:1px; background:#ffffff85; }
.scene-note { position:absolute; right:clamp(24px,5.5vw,84px); bottom:31px; max-width:280px; color:#fffdf4; font-family:Fraunces,serif; font-style:italic; font-size:15px; text-shadow:0 1px 5px #204a45aa; text-align:right; transition:opacity .35s; }
.play-area { position:relative; flex:1; padding:30px clamp(24px,7vw,105px) 16px; display:flex; flex-direction:column; background:var(--cream); }
.island-card { display:flex; align-items:center; justify-content:space-between; gap:28px; }
.eyebrow { color:#c58d50; font-size:10px; font-weight:700; letter-spacing:2.1px; text-transform:uppercase; }
h1 { margin:9px 0 8px; color:#31554a; font-family:Fraunces,serif; font-weight:600; font-size:clamp(30px,3.8vw,43px); letter-spacing:-1.6px; line-height:1.03; }
h1 em { color:#739480; font-weight:600; }
.card-copy p { margin:0; font-size:13px; color:#788c82; }
.card-stats { display:flex; align-items:center; gap:23px; padding:17px 24px; border:1px solid #e8eee5; border-radius:15px; background:#fbfcf6; min-width:250px; }
.stat { display:flex; align-items:center; gap:11px; }.stat-icon { color:#c78d50; font-size:22px; }.shell-icon { font-size:18px; }
.stat b { display:block; font-size:18px; line-height:1.1; color:#375a4d; }.stat small { display:block; margin-top:3px; font-size:10px; color:#8a9b91; white-space:nowrap; }
.stat-divider { width:1px; height:30px; background:#e7ece3; }
.action-row { display:flex; align-items:center; justify-content:space-between; gap:20px; margin-top:22px; padding-top:17px; border-top:1px solid #edf0e9; }
.hint { color:#83958c; font-size:12px; display:flex; align-items:center; gap:9px; }.hint-icon { color:#d4a266; font-size:17px; }
.cast-button { min-width:202px; height:49px; border:0; border-radius:10px; padding:0 17px; background:#396b56; color:white; font-size:13px; font-weight:700; letter-spacing:.1px; display:flex; align-items:center; justify-content:center; gap:10px; cursor:pointer; box-shadow:0 5px 12px #396b5628; transition:transform .16s,background .16s,box-shadow .16s; }
.cast-button:hover { background:#2e5e49; transform:translateY(-2px); box-shadow:0 8px 18px #396b5638; }.cast-button:active { transform:translateY(0); }.cast-button:focus-visible,.icon-button:focus-visible,.dialog-done:focus-visible { outline:3px solid #d59d5e; outline-offset:3px; }
.cast-button.biting { background:#c78d50; animation:button-pulse 1.5s ease-in-out infinite; }.cast-button.biting:hover { background:#b67d43; }
.button-icon { font-size:16px; }.button-key { border:1px solid #ffffff50; border-radius:4px; padding:3px 4px; font-size:8px; font-weight:600; opacity:.72; margin-left:3px; }
.collection-strip { margin-top:21px; padding:14px 0 2px; border-top:1px solid #edf0e9; }
.collection-heading { display:flex; justify-content:space-between; color:#82948a; font-size:9px; font-weight:700; letter-spacing:1.4px; }.collection-heading span:last-child { font-weight:500; letter-spacing:.15px; text-transform:none; }
.fish-list { display:flex; gap:8px; margin-top:10px; min-height:36px; }
.fish-chip { display:flex; align-items:center; gap:7px; border-radius:9px; border:1px solid #e9eee5; background:#fbfcf7; padding:6px 10px; color:#567164; font-size:10px; animation:appear .35s ease both; }.fish-chip .fish-emoji { font-size:15px; }.fish-chip .fish-total { color:#a0ada4; font-size:9px; }
.fish-placeholder { display:flex; align-items:center; gap:7px; color:#b3beb5; font-size:10px; }.fish-placeholder span { color:#cfaa7f; font-size:14px; }
.footer-note { margin-top:auto; padding-top:14px; color:#9cab9f; font-size:10px; text-align:center; letter-spacing:.2px; }.footer-note>span:first-child { color:#d0a570; margin-right:4px; }.footer-right { position:absolute; right:clamp(24px,7vw,105px); color:#b1bdb4; }
.toast { position:fixed; z-index:4; left:50%; top:28%; transform:translate(-50%,-8px); opacity:0; pointer-events:none; padding:12px 19px; border-radius:99px; background:#fffdf2ed; color:#426550; box-shadow:0 8px 30px #24473d22; font-size:12px; font-weight:600; transition:opacity .3s,transform .3s; white-space:nowrap; }.toast.show { opacity:1; transform:translate(-50%,0); }
.help-dialog { position:fixed; inset:0; margin:auto; width:min(410px,calc(100% - 34px)); border:1px solid #e5ece2; border-radius:20px; padding:34px 36px 30px; color:var(--ink); background:#fffdf6; box-shadow:0 20px 70px #173a302b; }.help-dialog::backdrop { background:#173a3055; backdrop-filter:blur(3px); }.dialog-close { position:absolute; top:13px; right:15px; border:0; background:none; color:#8a9a91; font-size:26px; cursor:pointer; }.dialog-flower { color:#d4a266; font-size:27px; margin-bottom:13px; }.help-dialog h2 { margin:8px 0 12px; font-family:Fraunces,serif; font-size:32px; color:#31554a; }.help-dialog p { color:#71867c; font-size:13px; line-height:1.7; }.dialog-done { width:100%; border:0; border-radius:9px; padding:13px; margin-top:9px; background:#396b56; color:#fff; cursor:pointer; font-weight:700; }
@keyframes button-pulse { 50% { box-shadow:0 5px 22px #c78d5066; } }@keyframes appear { from { opacity:0; transform:translateY(5px); } to {opacity:1;transform:translateY(0);} }
@media (min-height:950px) { .island-scene { height:65vh; max-height:730px; }.play-area { padding-top:38px; }.collection-strip { margin-top:26px; } }
@media (max-width:700px) { .game-shell { min-height:100svh; }.island-scene { height:54svh; min-height:350px; max-height:540px; }.topbar { top:17px; }.brand { font-size:19px; }.brand-mark { width:34px; height:34px; }.weather { padding:8px 10px; gap:5px; }.weather small { display:none; }.top-actions { gap:7px; }.icon-button { width:34px; height:34px; }.scene-caption { bottom:20px; font-size:9px; }.scene-note { right:22px; bottom:17px; max-width:160px; font-size:12px; }.play-area { padding:22px 23px 13px; }.island-card { align-items:flex-start; flex-direction:column; gap:16px; }h1 { font-size:34px; }.card-stats { min-width:0; padding:11px 17px; width:100%; justify-content:center; }.card-stats .stat { flex:1; justify-content:center; }.action-row { margin-top:16px; padding-top:14px; }.hint { font-size:10px; max-width:135px; }.cast-button { min-width:178px; height:46px; padding:0 11px; font-size:12px; gap:7px; }.collection-strip { margin-top:15px; padding-top:11px; }.collection-heading { font-size:8px; }.fish-list { gap:5px; flex-wrap:wrap; }.fish-chip { padding:5px 7px; gap:5px; font-size:9px; }.footer-note { padding-top:10px; font-size:9px; }.footer-right { display:none; } }
@media (max-width:390px) { .weather { padding:7px 8px; font-size:10px; }.weather-icon { font-size:15px; }.top-actions { gap:5px; }.topbar { left:16px; right:16px; }.play-area { padding-left:18px; padding-right:18px; }.cast-button { min-width:164px; }.button-key { display:none; }.island-scene { min-height:325px; } }
@media (prefers-reduced-motion:reduce) { *,*::before,*::after { animation-duration:.01ms !important; transition-duration:.01ms !important; } }

const canvas = document.getElementById('scene');
const ctx = canvas.getContext('2d');
const actionButton = document.getElementById('action-button');
const buttonLabel = document.getElementById('button-label');
const buttonIcon = document.getElementById('button-icon');
const statusCopy = document.getElementById('status-copy');
const hint = document.getElementById('hint');
const sceneNote = document.getElementById('scene-note');
const toast = document.getElementById('toast');
const fishList = document.getElementById('fish-list');
const fishes = [
  { name: 'Sunfin', emoji: '🐠', color: '#f5ad69', note: 'A little sunfin! It practically glows.' },
  { name: 'Bluegill', emoji: '🐟', color: '#84aeb4', note: 'A bluegill, cool as the morning tide.' },
  { name: 'Moon Koi', emoji: '🐡', color: '#e5ae9c', note: 'A moon koi! What a lovely surprise.' },
  { name: 'Sea Star', emoji: '⭐', color: '#efb771', note: 'A tiny sea star came to say hello.' },
  { name: 'Pufflet', emoji: '🐡', color: '#d8b695', note: 'A pufflet with the sweetest little face.' },
  { name: 'Silverling', emoji: '🐟', color: '#a8bdad', note: 'A silverling, shimmering in the light.' }
];
const counts = Array(fishes.length).fill(0);
let caught = 0;
let phase = 'idle';
let biteAt = 0;
let bobber = { x: 690, y: 430 };
let toastTimer;
let startedAt = performance.now();
let audioContext = null;
let ambience = null;
let soundOn = false;
let lastFrame = 0;

function resizeCanvas() {
  const rect = canvas.getBoundingClientRect();
  const dpr = Math.min(window.devicePixelRatio || 1, 2);
  canvas.width = Math.round(rect.width * dpr);
  canvas.height = Math.round(rect.height * dpr);
  ctx.setTransform(canvas.width / 1000, 0, 0, canvas.height / 650, 0, 0);
}
window.addEventListener('resize', resizeCanvas);
resizeCanvas();

function path(points, fill, stroke, width = 1) {
  ctx.beginPath();
  ctx.moveTo(points[0][0], points[0][1]);
  for (let i = 1; i < points.length; i++) ctx.lineTo(points[i][0], points[i][1]);
  ctx.closePath();
  if (fill) { ctx.fillStyle = fill; ctx.fill(); }
  if (stroke) { ctx.lineWidth = width; ctx.strokeStyle = stroke; ctx.stroke(); }
}
function ellipse(x, y, rx, ry, fill, rotation = 0) {
  ctx.beginPath(); ctx.ellipse(x, y, rx, ry, rotation, 0, Math.PI * 2); ctx.fillStyle = fill; ctx.fill();
}
function roundRect(x, y, w, h, r, fill) {
  ctx.beginPath(); ctx.roundRect(x, y, w, h, r); ctx.fillStyle = fill; ctx.fill();
}
function drawCloud(x, y, s, alpha) {
  ctx.save(); ctx.globalAlpha = alpha; ctx.fillStyle = '#fffdf0';
  ellipse(x, y, 44*s, 16*s, ctx.fillStyle); ellipse(x-27*s, y+5*s, 25*s, 12*s, ctx.fillStyle); ellipse(x+24*s, y+6*s, 30*s, 12*s, ctx.fillStyle); ellipse(x-5*s, y-8*s, 26*s, 18*s, ctx.fillStyle);
  ctx.restore();
}
function drawTree(x, y, s, color) {
  ctx.save(); ctx.translate(x, y); ctx.scale(s, s);
  path([[-5,4],[2,-31],[9,4]], '#8b7251');
  ellipse(-8,-26,14,17,color); ellipse(8,-33,17,20,color); ellipse(0,-46,14,16,color); ellipse(18,-21,12,15,color);
  ctx.restore();
}
function drawIsland(t) {
  // Faraway, hazy headland
  path([[0,315],[0,268],[70,260],[118,247],[174,256],[222,248],[276,261],[335,266],[399,258],[463,269],[526,267],[579,276],[630,267],[688,271],[749,257],[808,264],[865,254],[930,263],[1000,251],[1000,380],[0,380]], '#9dc7b6');
  // Little island and sandy rim
  ellipse(755,344,259,109,'#e8c994');
  ctx.beginPath(); ctx.moveTo(506,362); ctx.bezierCurveTo(552,277,622,258,698,270); ctx.bezierCurveTo(784,230,880,258,943,300); ctx.bezierCurveTo(1001,332,1008,374,1000,400); ctx.lineTo(507,400); ctx.closePath(); ctx.fillStyle='#618e6d'; ctx.fill();
  ctx.beginPath(); ctx.moveTo(564,329); ctx.bezierCurveTo(643,276,724,284,777,294); ctx.bezierCurveTo(842,282,899,301,946,326); ctx.strokeStyle='#7fa878'; ctx.lineWidth=7; ctx.lineCap='round'; ctx.stroke();
  drawTree(664,310,.75,'#416e58'); drawTree(713,291,1.05,'#49775c'); drawTree(764,302,.86,'#527f61'); drawTree(824,291,1.15,'#426e56'); drawTree(877,310,.79,'#578265'); drawTree(936,317,.58,'#477459');
  // Tiny cottage tucked in the palms
  roundRect(742,310,48,30,3,'#f3d9ae');
  path([[735,311],[766,287],[797,311]],'#bd8063');
  roundRect(758,319,11,21,2,'#8e9b78'); roundRect(775,317,9,9,2,'#a9c5b0');
  // little beach flecks
  ellipse(596,355,2,1,'#c7a773'); ellipse(614,361,3,1,'#c7a773'); ellipse(911,349,2,1,'#c7a773');
}
function drawDock(t) {
  // Pier shadow and supports
  path([[100,515],[479,518],[540,650],[72,650]], '#55776a');
  for (const x of [142,219,296,373,450]) {
    path([[x,490],[x+13,491],[x+20,627],[x+6,627]], '#a9784b');
  }
  // Deck planks
  path([[94,468],[472,468],[536,555],[42,555]], '#c99560');
  path([[94,468],[472,468],[536,555],[42,555]], null, '#b27d4f', 3);
  for (let i=1;i<7;i++) {
    const yy=468+i*12.2; const lx=94-(52/87)*(yy-468); const rx=472+(64/87)*(yy-468);
    ctx.beginPath();ctx.moveTo(lx,yy);ctx.lineTo(rx,yy);ctx.strokeStyle=i%2?'#b98253':'#d7aa73';ctx.lineWidth=1.5;ctx.stroke();
  }
  // End bollards and little coil of rope
  roundRect(88,464,12,20,4,'#a8754d'); roundRect(463,464,12,20,4,'#a8754d');
  ctx.beginPath();ctx.ellipse(135,488,12,4,.1,0,Math.PI*2);ctx.strokeStyle='#e7cf9f';ctx.lineWidth=2;ctx.stroke();
  // A soft mint fishing basket
  roundRect(128,519,48,29,6,'#789580');
  ctx.beginPath();ctx.moveTo(127,529);ctx.quadraticCurveTo(151,539,177,529);ctx.strokeStyle='#a5bba0';ctx.lineWidth=2;ctx.stroke();
}
function drawFisher(t) {
  // Tiny seated island visitor, in a warm mustard hat
  ellipse(370,488,35,7,'#31564c2a');
  // legs and boots
  path([[381,461],[398,478],[414,484],[408,491],[389,485],[369,470]],'#455e50');
  path([[402,479],[416,485],[421,491],[407,493],[396,486]],'#73533e');
  // sweater and back
  ctx.beginPath();ctx.moveTo(348,425);ctx.quadraticCurveTo(365,412,382,429);ctx.lineTo(390,463);ctx.quadraticCurveTo(369,477,344,459);ctx.closePath();ctx.fillStyle='#d27c54';ctx.fill();
  // neck and face
  roundRect(359,414,13,16,5,'#d7a27b'); ellipse(361,410,15,15,'#e5b68f');
  // cap
  ctx.beginPath();ctx.ellipse(360,399,19,10,-.1,Math.PI,Math.PI*2);ctx.fillStyle='#e8b965';ctx.fill();
  ctx.beginPath();ctx.ellipse(367,401,21,3,.1,0,Math.PI*2);ctx.fillStyle='#cf9d54';ctx.fill();
  // arm reaching toward the rod
  ctx.beginPath();ctx.moveTo(373,431);ctx.quadraticCurveTo(389,426,405,441);ctx.lineTo(420,448);ctx.lineTo(415,455);ctx.quadraticCurveTo(398,451,382,446);ctx.closePath();ctx.fillStyle='#d27c54';ctx.fill();
  // rod and line
  ctx.beginPath();ctx.moveTo(413,449);ctx.quadraticCurveTo(474,382,548,373);ctx.strokeStyle='#77583d';ctx.lineWidth=4;ctx.lineCap='round';ctx.stroke();
  ctx.beginPath();ctx.moveTo(548,373);ctx.quadraticCurveTo(600,411,bobber.x,bobber.y-4);ctx.strokeStyle='#fbf6dfaa';ctx.lineWidth=1;ctx.stroke();
  // little seated scarf
  ctx.beginPath();ctx.moveTo(351,430);ctx.quadraticCurveTo(365,437,379,429);ctx.lineTo(375,438);ctx.quadraticCurveTo(364,444,350,437);ctx.closePath();ctx.fillStyle='#f0d18a';ctx.fill();
}
function drawWater(t) {
  const water = ctx.createLinearGradient(0,272,0,650);
  water.addColorStop(0,'#83bdba'); water.addColorStop(.52,'#63aaa9'); water.addColorStop(1,'#438e92');
  ctx.fillStyle=water;ctx.fillRect(0,274,1000,376);
  // watery glow below the horizon
  const glow=ctx.createRadialGradient(690,320,8,690,320,390);glow.addColorStop(0,'#d6e5bb55');glow.addColorStop(1,'#e7e5b500');ctx.fillStyle=glow;ctx.fillRect(300,274,700,376);
  // long, lazy little wave marks
  for(let i=0;i<34;i++) {
    const seed=i*137.5; const x=((seed + t*(5+(i%3)*1.5))%1160)-80; const y=300+(i*47%345);
    const w=12+(i*19%46); const alpha=.10+(i%4)*.025;
    ctx.beginPath();ctx.ellipse(x,y,w,1.6,0,0,Math.PI);ctx.strokeStyle=`rgba(244,247,218,${alpha})`;ctx.lineWidth=1.4;ctx.stroke();
  }
  // shimmering sunlight trail
  for(let i=0;i<13;i++) { const y=319+i*13; const x=647+(i%4)*17+Math.sin(t*.4+i)*8; ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x+17+(i%3)*10,y);ctx.strokeStyle=`rgba(255,244,197,${.11-i*.005})`;ctx.lineWidth=2;ctx.stroke(); }
}
function drawBobber(t) {
  if(phase==='idle') return;
  const bobY=bobber.y+Math.sin(t*2.7)*2;
  if(phase==='bite') {
    const pulse=(Math.sin(t*8)+1)/2;
    for(let i=0;i<3;i++){ctx.beginPath();ctx.ellipse(bobber.x,bobY,11+i*9+pulse*5,3+i*2+pulse*2,0,0,Math.PI*2);ctx.strokeStyle=`rgba(255,245,200,${.48-i*.12})`;ctx.lineWidth=1.6;ctx.stroke();}
    ellipse(bobber.x,bobY,5,5,'#fff6d5');
  }
  // float
  ctx.beginPath();ctx.moveTo(bobber.x-5,bobY-10);ctx.lineTo(bobber.x+5,bobY-10);ctx.lineTo(bobber.x+3,bobY+2);ctx.quadraticCurveTo(bobber.x,bobY+7,bobber.x-3,bobber.y+2);ctx.closePath();ctx.fillStyle='#f3eee0';ctx.fill();
  ctx.beginPath();ctx.moveTo(bobber.x-4,bobY-1);ctx.lineTo(bobber.x+4,bobY-1);ctx.lineTo(bobber.x+3,bobY+3);ctx.quadraticCurveTo(bobber.x,bobY+6,bobber.x-3,bobberY+3);ctx.closePath();ctx.fillStyle='#dc8366';ctx.fill();
}
function drawScene(now) {
  const t=(now-startedAt)/1000;
  ctx.clearRect(0,0,1000,650);
  const sky=ctx.createLinearGradient(0,0,0,350);sky.addColorStop(0,'#b9dcd3');sky.addColorStop(.62,'#d3e6cf');sky.addColorStop(1,'#f1e7c8');ctx.fillStyle=sky;ctx.fillRect(0,0,1000,350);
  // sun
  const sx=724,sy=115;const sunG=ctx.createRadialGradient(sx,sy,7,sx,sy,63);sunG.addColorStop(0,'#fff8d5');sunG.addColorStop(.72,'#f8e5ad');sunG.addColorStop(1,'#f8e5ad00');ctx.fillStyle=sunG;ctx.beginPath();ctx.arc(sx,sy,64,0,Math.PI*2);ctx.fill();ellipse(sx,sy,27,27,'#fff4ce');
  drawCloud(161+Math.sin(t*.035)*14,105,1.05,.75);drawCloud(431+Math.sin(t*.027)*10,155,.7,.47);drawCloud(889+Math.sin(t*.03)*8,92,.68,.44);
  drawIsland(t);drawWater(t);drawBobber(t);drawDock(t);drawFisher(t);
  // Foreground sprigs framing the cove
  for(const [x,y,s] of [[17,581,1],[950,594,.9],[985,548,.62],[20,540,.7]]) {
